BEGIN;
CREATE SCHEMA IF NOT EXISTS tool_lending;
SET search_path TO tool_lending, public;
CREATE TYPE member_tier AS ENUM ('STANDARD', 'SUPPORTER', 'STAFF');
CREATE TYPE tool_status AS ENUM ('AVAILABLE', 'RESERVED', 'CHECKED_OUT', 'MAINTENANCE');
CREATE TYPE reservation_status AS ENUM ('ACTIVE', 'FULFILLED', 'CANCELLED', 'EXPIRED');
CREATE TYPE loan_status AS ENUM ('OPEN', 'RETURNED');
CREATE TABLE members (member_id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, display_name varchar(120) NOT NULL, tier member_tier NOT NULL DEFAULT 'STANDARD', active boolean NOT NULL DEFAULT true, joined_on date NOT NULL DEFAULT CURRENT_DATE);
CREATE TABLE tools (tool_id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, asset_tag varchar(24) NOT NULL UNIQUE, display_name varchar(120) NOT NULL, daily_late_fee numeric(10,2) NOT NULL CHECK (daily_late_fee >= 0), status tool_status NOT NULL DEFAULT 'AVAILABLE', version integer NOT NULL DEFAULT 1);
CREATE TABLE reservations (reservation_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, tool_id integer NOT NULL REFERENCES tools(tool_id), member_id integer NOT NULL REFERENCES members(member_id), starts_on date NOT NULL, ends_on date NOT NULL, status reservation_status NOT NULL DEFAULT 'ACTIVE', created_at timestamptz NOT NULL DEFAULT clock_timestamp(), CHECK (ends_on >= starts_on));
CREATE UNIQUE INDEX ux_active_reservation_tool ON reservations(tool_id) WHERE status = 'ACTIVE';
CREATE TABLE loans (loan_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, tool_id integer NOT NULL REFERENCES tools(tool_id), member_id integer NOT NULL REFERENCES members(member_id), checked_out_at timestamptz NOT NULL DEFAULT clock_timestamp(), due_on date NOT NULL, returned_at timestamptz, late_fee numeric(10,2) NOT NULL DEFAULT 0 CHECK (late_fee >= 0), status loan_status NOT NULL DEFAULT 'OPEN');
CREATE UNIQUE INDEX ux_open_loan_tool ON loans(tool_id) WHERE status = 'OPEN';
CREATE TABLE idempotency_records (operation varchar(32) NOT NULL, idempotency_key uuid NOT NULL, request_hash char(64) NOT NULL, response_json jsonb, http_status integer, created_at timestamptz NOT NULL DEFAULT clock_timestamp(), PRIMARY KEY (operation, idempotency_key));
CREATE TABLE audit_log (audit_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, occurred_at timestamptz NOT NULL DEFAULT clock_timestamp(), actor varchar(100) NOT NULL, operation varchar(40) NOT NULL, entity_type varchar(40) NOT NULL, entity_id varchar(80) NOT NULL, request_id uuid NOT NULL, details jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE INDEX ix_audit_occurred_at ON audit_log(occurred_at DESC);
CREATE INDEX ix_loans_member_status ON loans(member_id, status);
CREATE INDEX ix_reservations_member_status ON reservations(member_id, status);
COMMIT;
